@Component("businessUnit-handler")
@ProcessingGroup("businessUnit-processing-group")
public class BusinessUnitEventHandler {
	
	// core constructor
	BusinessUnitEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateBusinessUnitEvent
     */
    @EventHandler
    public void handle( CreateBusinessUnitEvent event) {
        entityManager.persist(new BusinessUnit(event.getBusinessUnitId(), event.getName(), event.getLeader(), event.getOrganization(), event.getAudits()));
    }

    /*
     * @param	event UpdateBusinessUnitEvent
     */
    @EventHandler
    public BusinessUnit handle( UpdateBusinessUnitEvent event) {
    	entityManager.merge(new BusinessUnit(event.getBusinessUnitId(), event.getName(), event.getLeader(), event.getOrganization(), event.getAudits()));
    }
    
    /*
     * @param	event DeleteBusinessUnitEvent
     */
    @EventHandler
    public void on( DeleteBusinessUnitEvent event) {
    	BusinessUnit entity = new BusinessUnit();
   
    	// ------------------------------------------
    	// apply the BusinessUnitId
    	// ------------------------------------------
    	entity.setBusinessUnitId( event.getBusinessUnitId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final BusinessUnitRepository businessUnitEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(BusinessUnitEventHandler.class.getName());

}
